def harmonic_mean(a, b):
    return 2 * a * b / (a + b)

def f1_score(precision, recall):
    if precision + recall == 0:
        return 0.0
    return 2 * precision * recall / (precision + recall)

test_cases = [(0.9, 0.9), (1.0, 0.5), (1.0, 0.01), (0.6, 0.6)]

for p, r in test_cases:
    print(f"precision={p}, recall={r} -> "
          f"harmonic_mean={harmonic_mean(p, r):.4f}, f1={f1_score(p, r):.4f}")

