def average_growth_rate(yearly_growth_pct):
    # yearly_growth_pct is a list like [20, -10, 15, 30] meaning +20%, -10%, etc.
    return sum(yearly_growth_pct) / len(yearly_growth_pct)

growth = [20, -10, 15, 30]
print(average_growth_rate(growth))   # reports 13.75
